package mrpapermoon.whisper.mesh.dbimport androidx.room.ColumnInfoimport androidx.room.Entityimport androidx.room.PrimaryKeyimport kotlinx.serialization.InternalSerializationApiimport kotlinx.serialization.Serializable@InternalSerializationApi @Serializable@Entity(tableName = NetworkMessageEntity.TABLE_NAME)class NetworkMessageEntity(	@PrimaryKey	val hash: Long,	val whispererId: String,	val timestamp: Long,	@ColumnInfo(typeAffinity = ColumnInfo.BLOB)	val payload: ByteArray,) {	companion object {		internal const val TABLE_NAME = "known_messages"	}}